    b = '' if b is None else str(b)
    # If one is empty, distance is length of the other.
    if not a:
        return len(b)
    if not b:
        return len(a)
    # Ensure a is the longer string to minimize inner loop size.
    if len(a) < len(b):
        a, b = b, a
    n, m = len(a), len(b)
