def solve(a, b):
    """Levenshtein distance between two sequences.
    Accepts strings, lists, tuples, or any iterable of hashable items.
    Uses O(min(n, m)) space DP for efficiency.
    """
    # Normalise None to empty sequence
    if a is None:
        a = []
    if b is None:
        b = []
    # If inputs are strings, keep as is; otherwise convert to list
    if isinstance(a, str):
        seq_a = a
    else:
        seq_a = list(a)
    if isinstance(b, str):
        seq_b = b
    else:
        seq_b = list(b)
    # Quick equality check
    if seq_a == seq_b:
        return 0
    n, m = len(seq_a), len(seq_b)
    # If one is empty
    if n == 0:
        return m
    if m == 0:
        return n
    # Ensure seq_a is the longer to minimise inner loop size
    if n < m:
        seq_a, seq_b = seq_b, seq_a
        n, m = m, n
    # DP rows: previous row distances for transforming empty prefix of seq_a to prefixes of seq_b
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i]
        ai = seq_a[i - 1]
        for j in range(1, m + 1):
            if ai == seq_b[j - 1]:
                cur.append(prev[j - 1])
            else:
                cur.append(1 + min(prev[j], cur[-1], prev[j - 1]))
        prev = cur
    return prev[m]

