    if isinstance(b, (bytes, bytearray)):
        b = b.decode('utf-8', errors='ignore')
    # Ensure we are working with strings (in case other types are passed)
    a = str(a)
    b = str(b)
    # Quick equality shortcut
    if a == b:
        return 0
    # If either string is empty
    if not a:
        return len(b)
    if not b:
        return len(a)
    # Ensure ``a`` is the longer string to minimise inner loop size
    if len(a) < len(b):
        a, b = b, a
    n, m = len(a), len(b)
    # ``prev`` holds distances for transforming the empty prefix of ``a``
    # to prefixes of ``b``.
    prev = list(range(m + 1))
